INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Kundenbeziehungen > Gesetz gegen unlauteren Wettbewerb
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Schützt das Gesetz gegen unlauteren Wettbewerb (UWG) ausschließlich die Interessen der Verbraucher?', 2, '[{"text": "Nein", "correct": true, "because": "Es schützt auch Mitbewerber und die Allgemeinheit"}, {"text": "Ja", "correct": false, "because": "Schutz ist dreigliedrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist jede Form von vergleichender Werbung nach dem Gesetz gegen unlauteren Wettbewerb verboten?', 2, '[{"text": "Nein", "correct": true, "because": "Sie ist erlaubt, wenn sie lauter ist (§ 6 UWG)"}, {"text": "Ja", "correct": false, "because": "Vergleichende Werbung ist reguliert, nicht verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine irreführende Werbung nach dem UWG auch dann unlauter sein, wenn sie keinen finanziellen Schaden verursacht?', 2, '[{"text": "Ja", "correct": true, "because": "Spürbare Beeinträchtigung reicht aus (§ 3 UWG)"}, {"text": "Nein", "correct": false, "because": "Schaden ist nicht zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Unternehmen nach dem UWG Kunden ohne Einwilligung mit Telefonwerbung kontaktieren?', 2, '[{"text": "Nein", "correct": true, "because": "§ 7 UWG verlangt ausdrückliche Zustimmung"}, {"text": "Ja", "correct": false, "because": "Ohne Einwilligung ist es unzulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Gesetz gegen unlauteren Wettbewerb nur auf den Schutz vor aggressiven Verkaufspraktiken beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Es umfasst auch Irreführung und mehr (§ 3-7 UWG)"}, {"text": "Ja", "correct": false, "because": "Schutzbereich ist breiter"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das Gesetz gegen unlauteren Wettbewerb primär?', 2, '[{"text": "Schutz vor unlauteren Geschäftspraktiken", "correct": true, "because": "§ 1 UWG definiert dies klar"}, {"text": "Maximierung von Unternehmensgewinnen", "correct": false, "because": "Kein gesetzliches Ziel"}, {"text": "Regulierung von Steuersätzen", "correct": false, "because": "Steuerrecht ist separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Instanz kann Verstöße gegen das UWG mit Bußgeldern ahnden?', 3, '[{"text": "Behörden", "correct": true, "because": "§ 19 UWG regelt Bußgelder durch Behörden"}, {"text": "Mitbewerber", "correct": false, "because": "Sie können nur zivilrechtlich klagen"}, {"text": "Kunden selbst", "correct": false, "because": "Keine direkte Ahndungsbefugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Werbung ist nach § 5 UWG als unlauter einzustufen?', 2, '[{"text": "Irreführende Werbung", "correct": true, "because": "§ 5 UWG verbietet Irreführung"}, {"text": "Humorvolle Werbung", "correct": false, "because": "Nicht per se unlauter"}, {"text": "Preiswerbung", "correct": false, "because": "Nur bei Täuschung unlauter"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist nach dem UWG berechtigt, Unterlassungsansprüche geltend zu machen?', 2, '[{"text": "Mitbewerber", "correct": true, "because": "§ 8 UWG nennt Mitbewerber"}, {"text": "Lieferanten", "correct": false, "because": "Keine direkte Berechtigung"}, {"text": "Aktionäre", "correct": false, "because": "Nicht im Schutzbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht laut UWG bei unerlaubter Telefonwerbung?', 2, '[{"text": "Bußgeld bis 300.000 Euro", "correct": true, "because": "§ 20 UWG legt dies fest"}, {"text": "Verwarnung ohne Strafe", "correct": false, "because": "Verwarnung nicht vorgesehen"}, {"text": "Pflicht zur Entschuldigung", "correct": false, "because": "Keine gesetzliche Regelung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Parteien schützt das Gesetz gegen unlauteren Wettbewerb?', 4, '[{"text": "Mitbewerber", "correct": true, "because": "§ 1 UWG schützt Mitbewerber"}, {"text": "Verbraucher", "correct": true, "because": "§ 1 UWG schützt Verbraucher"}, {"text": "Allgemeinheit", "correct": true, "because": "§ 1 UWG schützt unverfälschten Wettbewerb"}, {"text": "Steuerbehörden", "correct": false, "because": "Nicht im Schutzbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken verbietet das UWG explizit?', 3, '[{"text": "Irreführende Angaben", "correct": true, "because": "§ 5 UWG regelt dies"}, {"text": "Aggressive Verkaufsmethoden", "correct": true, "because": "§ 4a UWG verbietet Aggressivität"}, {"text": "Unerlaubte Telefonwerbung", "correct": true, "because": "§ 7 UWG schützt vor Belästigung"}, {"text": "Rabattaktionen", "correct": false, "because": "Nicht per se verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansprüche können bei einem Verstoß gegen das UWG geltend gemacht werden?', 4, '[{"text": "Unterlassung", "correct": true, "because": "§ 8 UWG regelt Unterlassung"}, {"text": "Schadensersatz", "correct": true, "because": "§ 9 UWG erlaubt Schadensersatz"}, {"text": "Gewinnabschöpfung", "correct": true, "because": "§ 10 UWG ermöglicht dies"}, {"text": "Steuererleichterung", "correct": false, "because": "Kein UWG-Anspruch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien machen eine Werbung nach § 3 UWG unlauter?', 3, '[{"text": "Fehlende Sorgfalt", "correct": true, "because": "§ 3 Abs. 2 UWG fordert Sorgfalt"}, {"text": "Beeinträchtigung der Entscheidungsfreiheit", "correct": true, "because": "§ 3 Abs. 2 UWG schützt Entscheidungen"}, {"text": "Spürbare Beeinflussung", "correct": true, "because": "§ 3 Abs. 1 UWG setzt dies voraus"}, {"text": "Kreative Gestaltung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gruppen können nach § 8 UWG Unterlassungsklagen erheben?', 3, '[{"text": "Mitbewerber", "correct": true, "because": "§ 8 Abs. 3 UWG nennt Mitbewerber"}, {"text": "Verbraucherverbände", "correct": true, "because": "§ 8 Abs. 3 Nr. 2 UWG erlaubt dies"}, {"text": "Wirtschaftsverbände", "correct": true, "because": "§ 8 Abs. 3 Nr. 3 UWG befugt sie"}, {"text": "Privatpersonen ohne Interesse", "correct": false, "because": "Keine Berechtigung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das UWG schützt den unverfälschten Wettbewerb. b) Es gilt nur für Online-Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "§ 1 UWG schützt Wettbewerb, gilt allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Irreführende Werbung ist nach § 5 UWG verboten. b) Vergleichende Werbung ist immer unlauter.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "§ 5 ja, § 6 erlaubt lautere Vergleiche"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das UWG erlaubt Schadensersatzansprüche bei Vorsatz. b) Bußgelder sind nur bei Straftaten möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "§ 9 ja, § 19 regelt Bußgelder allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Telefonwerbung ohne Zustimmung ist nach § 7 UWG unlauter. b) Verbraucher können direkt Bußgelder verhängen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "§ 7 ja, Bußgelder nur Behörden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das UWG verbietet aggressive Geschäftspraktiken. b) Unterlassungsansprüche sind nur für Großunternehmen möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "§ 4a ja, § 8 gilt allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

